import{c as t,Q as e,j as r,m as l}from"./chunks/framework.rWdQudnF.js";const x=JSON.parse('{"title":"计算机组成","description":"","frontmatter":{"title":"计算机组成"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/index.md","filePath":"综合知识/系统基础/计算机组成/index.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/index.md"};function h(i,a,n,c,s,p){return e(),r("div",null,[...a[0]||(a[0]=[l('<ul><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/CPU与指令系统/计算机硬件组成.html">计算机硬件组成</a>（5大部件/冯·诺依曼结构）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/CPU与指令系统/CPU组成与功能.html">CPU 组成与功能</a>（运算器 ALU+AC+DR+PSW / 控制器 IR+PC+AR+ID）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/CPU与指令系统/CPU组成与功能.html">CPU 功能与频率</a>（主频=外频×倍频）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/CPU与指令系统/指令系统.html">指令系统</a>（组成/执行过程/寻址方式 / CISC vs RISC）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/CPU与指令系统/Flynn分类法.html">Flynn 分类法</a>（SISD/SIMD/MISD/MIMD）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/CPU与指令系统/指令流水线.html">指令流水线</a>（周期/执行时间/吞吐率/加速比 / 超流水线/超标量/VLIW / 超线程）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/存储与IO系统/存储系统.html">存储体系与分级存储</a>（Cache/主存/辅存 / 局部性原理 / 相联存取 / 易失性分类 / DRAM/DDR）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/存储与IO系统/存储系统.html">Cache 地址映射</a>（直接/全相联/组相联）+ 替换算法 + 命中率计算</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/存储与IO系统/存储系统.html">磁盘结构与调度算法</a>（FCFS/SSTF/SCAN/CSCAN）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/存储与IO系统/总线结构.html">总线结构</a>（内部/系统/外部总线 / 数据+地址+控制 / 串行vs并行）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/存储与IO系统/输入输出技术.html">I/O 编址</a>（独立编址 vs 统一编址）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/存储与IO系统/输入输出技术.html">数据交互方式</a>（程序查询/中断/DMA）+ 中断响应时机 + DMA响应时机</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/RAID技术.html">RAID 技术</a>（0/1/5/6/10 特性与容量计算）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/IO缓冲技术.html">I/O 缓冲技术</a>（单缓冲/双缓冲时间计算）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/内存地址与芯片计算.html">内存地址与芯片计算</a>（十六进制地址范围/芯片数量）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/硬盘容量与存取时间.html">硬盘容量与存取时间</a>（格式化容量/存取时间组成）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/接口类型.html">接口类型</a>（网络/显示/存储/串行接口 / A/D转换）</p></li><li><p>[x] <a href="/arch-exam/综合知识/系统基础/计算机组成/处理器分类.html">处理器分类</a>（通用/专用/AI芯片架构/RISC-V）</p></li><li><p>[x] 消息中间件（消息队列/发布订阅/点对点 — 属嵌入式中间件范畴，内容见嵌入式章节）</p></li></ul><hr><p>笔记</p><p>计算机硬件</p><hr><h3 id="校验码" tabindex="-1">校验码 <a class="header-anchor" href="#校验码" aria-label="Permalink to &quot;校验码&quot;">​</a></h3><p>码距：就单个编码A:00而言，其码距为1，因为其只需要改变一位就变成另一个编码。在两个编码中，从A码到B码转换所需要改变的位数称为码距，如A:00要转换为B:11,码距为2。</p><p>一般来说，码距越大，越利于纠错和检错。</p><hr><blockquote><p><strong>码距</strong>：两个编码之间至少需要改变的位数。码距越大，检错纠错能力越强。</p></blockquote><table tabindex="0"><thead><tr><th>校验码</th><th style="text-align:center;">能力</th><th>关键特性</th></tr></thead><tbody><tr><td><strong>奇偶校验</strong></td><td style="text-align:center;">检错（仅奇数位）</td><td>增加 1 位校验位使 1 的个数为奇/偶，码距=2，<strong>不能纠错</strong></td></tr><tr><td><strong>海明码</strong></td><td style="text-align:center;">检错 + <strong>纠错</strong>（1位）</td><td>校验位在 2 的幂次方位置（1,2,4,8...），公式 <strong>2^k ≥ n+k+1</strong></td></tr><tr><td><strong>CRC</strong></td><td style="text-align:center;">检错</td><td>模 2 除法（异或），只能检错<strong>不能纠错</strong>，约定生成多项式 G(x)</td></tr></tbody></table><p><strong>海明码解题流程</strong>：确定校验位数量 k（2^k ≥ n+k+1）→ 校验位放 2 的幂次方位置 → 按位负责关系计算各校验位（偶校验）→ 写出编码。</p><p><strong>CRC 解题流程</strong>：原始信息后补 r 个 0（r = G(x) 最高次）→ G(x) 转二进制除数 → 模 2 除法得余数 → 拼接发送。</p><h4 id="奇偶校验码" tabindex="-1">奇偶校验码 <a class="header-anchor" href="#奇偶校验码" aria-label="Permalink to &quot;奇偶校验码&quot;">​</a></h4><p>在编码中增加1位校验位来使编码中1的个数为奇数（奇校验）或者偶数（偶校验），从而使码距变为2。</p><p>奇校验可以检测编码中奇数个数据位出错，即当合法编码中的奇数位发生了错误时，即编码中的1变成0或者0变成1，则该编码中1的个数的奇偶性就发生了变化，从而检查出错误。</p><p><strong>但无法纠错</strong>。</p><h4 id="循环冗余校验码-crc" tabindex="-1">循环冗余校验码 CRC <a class="header-anchor" href="#循环冗余校验码-crc" aria-label="Permalink to &quot;循环冗余校验码 CRC&quot;">​</a></h4><p>CRC只能检错，不能纠错，</p><p>其原理是找出一个能整除多项式的编码，因此首先要将原始报文除以多项式，将所得的余数作为校验位加在原始报文之后，作为发送数据发给接收方。</p><p>使用CRC编码，需要先约定一个生成多项式G(x)。生成多项式的最高位和最低位必须是1。假设原始信息有位，则对应多项式M(x)。生成校验码思想就是在原始信息位后追加若干校验位，使得追加的信息能被G(x)整除。接收方接收到带校验位的信息，然后用G(x)整除。余数为0，则没有错误；反之则发生错误。</p><hr><p><strong>例</strong>：假设原始信息串为 <code>10110</code>，CRC 的生成多项式为 ( G(x)=x^4+x+1 )，求 CRC 校验码。</p><ul><li>（1）确定生成多项式的阶数并添零</li></ul><p>生成多项式的最高次幂为 ( r = 4 )。</p><p>在原始信息位后添加 ( r ) 个 0，得到被除数：</p><p><code>10110</code> + <code>0000</code> = <strong><code>101100000</code></strong></p><ul><li>（2）由多项式得到除数（生成多项式对应的二进制串）</li></ul><p>多项式 ( x^4 + x + 1 ) 中，幂指数 4、1、0 的系数为 1，幂指数 3、2 的系数为 0。</p><p>因此对应的二进制串为 <strong><code>10011</code></strong>（从 ( x^4 ) 到 ( x^0 ) 排列）。</p><ul><li>（3）模 2 除法计算 CRC 校验码</li></ul><p>模 2 除法采用<strong>异或</strong>运算（不进位、不借位）。</p><p>将被除数 <code>101100000</code> 与除数 <code>10011</code> 进行模 2 除，过程如下：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260518013557.png" alt="image.png"></p><p>得到余数 <strong><code>1111</code></strong>。</p><blockquote><p><strong>注意</strong>：余数的位数应与生成多项式的阶数 ( r ) 相同。若余数不足 ( r ) 位，则需要在左边补 0 至 ( r ) 位。本例余数为 4 位，无需补齐。</p></blockquote><ul><li>（4）生成最终发送的信息串</li></ul><p>将计算得到的 CRC 校验码（余数）附加在原始信息串后面：<br> 原始信息 <code>10110</code> + 余数 <code>1111</code> = <strong><code>101101111</code></strong><br> 发送方将此数据帧发送给接收方。</p><ul><li>（5）接收方校验</li></ul><p>接收方收到带校验码的帧后，用<strong>相同的生成多项式</strong> <code>10011</code> 进行模 2 除法。</p><ul><li>若余数为 <strong>0</strong>，说明传输无错误（或错误概率极低）；</li><li>若余数不为 0，则说明数据在传输过程中发生了错误，请求发送方重传。</li></ul><p>注意：收发信息双方需使用相同的生成多项式。</p><hr><h3 id="计算机硬件和指令" tabindex="-1">计算机硬件和指令 <a class="header-anchor" href="#计算机硬件和指令" aria-label="Permalink to &quot;计算机硬件和指令&quot;">​</a></h3><h4 id="计算机硬件组成" tabindex="-1">计算机硬件组成 <a class="header-anchor" href="#计算机硬件组成" aria-label="Permalink to &quot;计算机硬件组成&quot;">​</a></h4><blockquote><p>计算机基本硬件系统由<strong>运算器、控制器、存储器、输入设备、输出设备</strong>5大部件组成。</p></blockquote><p>运算器 + 控制器 = <strong>CPU（中央处理单元）</strong>，是硬件系统核心。存储器分为内部（速度快容量小）和外部（容量大速度慢）。输入输出设备合称外设。</p><p><strong>冯·诺依曼结构</strong>：将计算机硬件划分为上述 5 部分。DSP 常采用<strong>哈佛体系结构</strong>（程序和数据分开存储）。</p><p><strong>专用处理器：</strong> GPU（数百/数千核并行计算）、DSP（实时数字信号处理）、FPGA（现场可编程门阵列）。</p><h3 id="指令系统-cisc-和-risc" tabindex="-1">指令系统 CISC 和 RISC <a class="header-anchor" href="#指令系统-cisc-和-risc" aria-label="Permalink to &quot;指令系统 CISC 和 RISC&quot;">​</a></h3><h4 id="流水线原理" tabindex="-1">流水线原理 <a class="header-anchor" href="#流水线原理" aria-label="Permalink to &quot;流水线原理&quot;">​</a></h4><h4 id="流水线时间计算" tabindex="-1">流水线时间计算 <a class="header-anchor" href="#流水线时间计算" aria-label="Permalink to &quot;流水线时间计算&quot;">​</a></h4><h3 id="存储系统" tabindex="-1">存储系统 <a class="header-anchor" href="#存储系统" aria-label="Permalink to &quot;存储系统&quot;">​</a></h3><h4 id="计算机存储结构层次图" tabindex="-1">计算机存储结构层次图 <a class="header-anchor" href="#计算机存储结构层次图" aria-label="Permalink to &quot;计算机存储结构层次图&quot;">​</a></h4><h4 id="局部性原理" tabindex="-1">局部性原理 <a class="header-anchor" href="#局部性原理" aria-label="Permalink to &quot;局部性原理&quot;">​</a></h4><h4 id="高速缓存-cache" tabindex="-1">高速缓存 Cache <a class="header-anchor" href="#高速缓存-cache" aria-label="Permalink to &quot;高速缓存 Cache&quot;">​</a></h4><h4 id="虚拟存储器" tabindex="-1">虚拟存储器 <a class="header-anchor" href="#虚拟存储器" aria-label="Permalink to &quot;虚拟存储器&quot;">​</a></h4><h4 id="磁盘" tabindex="-1">磁盘 <a class="header-anchor" href="#磁盘" aria-label="Permalink to &quot;磁盘&quot;">​</a></h4><h3 id="输入输出技术" tabindex="-1">输入输出技术 <a class="header-anchor" href="#输入输出技术" aria-label="Permalink to &quot;输入输出技术&quot;">​</a></h3><h3 id="总线" tabindex="-1">总线 <a class="header-anchor" href="#总线" aria-label="Permalink to &quot;总线&quot;">​</a></h3>',60)])])}const m=t(o,[["render",h]]);export{x as __pageData,m as default};
